    VelaWarningSpeaker speaker; Guide guide; Engine engine; Results results;PendingExecutor outputs;
    @Before public void setup(){engine=new Engine();guide=new Guide(engine);outputs=new PendingExecutor();speaker=new VelaWarningSpeaker(outputs);speaker.bind(guide);results=new Results();}
    @After public void cleanup(){speaker.close();while(!outputs.jobs.isEmpty())outputs.next();engine.shutdown();Shadows.shadowOf(Looper.getMainLooper()).idle();}
    public static class Engine extends TextToSpeech {
        int calls,leadCalls,stops,result=SUCCESS;String text,id;Locale language;Voice selected;
        Engine(){super(RuntimeEnvironment.getApplication(),null);}
        @Override public int isLanguageAvailable(Locale locale){return locale.getLanguage().equals("nl")||locale.getLanguage().equals("en")?LANG_AVAILABLE:LANG_NOT_SUPPORTED;}
        @Override public Set<Voice> getVoices(){return new HashSet<>(Arrays.asList(new Voice("nl-offline",Locale.forLanguageTag("nl-NL"),400,100,false,Collections.emptySet()),new Voice("en-offline",Locale.US,400,100,false,Collections.emptySet())));}
        @Override public Voice getVoice(){return selected;}
        @Override public int setVoice(Voice voice){selected=voice;return SUCCESS;}
        @Override public boolean isSpeaking(){return false;}
        @Override public int setLanguage(Locale locale){language=locale;return isLanguageAvailable(locale);}
        @Override public int playSilentUtterance(long ms,int queue,String id){leadCalls++;assertEquals(QUEUE_ADD,queue);assertTrue(id.startsWith("vela-lead-warning-"));return SUCCESS;}
        @Override public int stop(){stops++;return SUCCESS;}
        @Override public int speak(CharSequence text,int queue,Bundle b,String id){calls++;this.text=text.toString();this.id=id;assertEquals(QUEUE_ADD,queue);return result;}
    }
    public static class StaticTrack extends AudioTrack {
        int state=AudioTrack.STATE_NO_STATIC_DATA,writes;boolean partial,badAfter;
        StaticTrack(){super(AudioManager.STREAM_MUSIC,22050,android.media.AudioFormat.CHANNEL_OUT_MONO,android.media.AudioFormat.ENCODING_PCM_16BIT,12000,AudioTrack.MODE_STATIC);}
        @Override public int getState(){return state;}
        @Override public int write(short[] data,int offset,int count){writes++;state=badAfter?AudioTrack.STATE_UNINITIALIZED:AudioTrack.STATE_INITIALIZED;return partial?count-1:count;}
    }
    public static class Guide {
        public TextToSpeech b;public float d=.7f;public boolean e=true,h=true,i=false,m=false,n=false,o=false;public int s,releases,request=AudioManager.AUDIOFOCUS_REQUEST_GRANTED;
        public Object p=new Object(),l,q=new Object();public boolean t;public int focusRequests;public float c=1f;public String j="en",preflightLanguage;public Collection<Object> g=new ArrayList<>();public Closure closure;
        Guide(Engine engine){b=engine;}
        public boolean b(){s++;if(!t){focusRequests++;VelaWarningSpeaker.focusRequest(this);VelaWarningSpeaker.focusResult(this,request);t=request!=0;}return true;}
        public void j(String text,boolean interrupt,boolean ignoreMute){assertFalse(interrupt);assertFalse(ignoreMute);preflightLanguage=VelaWarningSpeaker.language(this,"fr");if(VelaWarningSpeaker.neuralSpeech(this))return;b();closure=new Closure(this,b);VelaWarningSpeaker.capture(closure);}
        public void f(){releases++;if(s>0)s--;}
    }
    public static class Closure {public byte f=1;public Object h,i;Closure(Guide g,TextToSpeech t){h=g;i=t;}}
    public static class NativeListener {public Object a;NativeListener(Guide g){a=g;}}
    public static class NavState {
        public int a=2,f=0,j=1,k=3,n=-1;public double b=80,c=2000,d=300,i=1400,m=-1;public boolean e=false,g=false,l=false;
        public Set<Integer> h=new HashSet<>(Arrays.asList(0,1));
        public NavState(){}
        public NavState(int a,double b,double c,double d,boolean e,int f,boolean g,Set<Integer> h,double i,int j,int k,boolean l,double m,int n){this.a=a;this.b=b;this.c=c;this.d=d;this.e=e;this.f=f;this.g=g;this.h=h;this.i=i;this.j=j;this.k=k;this.l=l;this.m=m;this.n=n;}
    }
    public static class NativeSession {public Object b;public NativeFlow f=new NativeFlow();NativeSession(Guide guide,Object route){b=guide;f.value.d=route;}}
    public static class NativeFlow {public NativeSnapshot value=new NativeSnapshot();public Object getValue(){return value;}}
    public static class NativeSnapshot {public boolean a=true,b=false,c=false;public Object d;}
    public static class PendingExecutor extends java.util.concurrent.AbstractExecutorService {
        public final Queue<Runnable> jobs=new ArrayDeque<>();public void execute(Runnable job){jobs.add(job);}public void shutdown(){}public List<Runnable> shutdownNow(){return new ArrayList<>(jobs);}public boolean isShutdown(){return false;}public boolean isTerminated(){return false;}public boolean awaitTermination(long n,java.util.concurrent.TimeUnit unit){return false;}void next(){jobs.remove().run();}
    }
    public static class Level {public double a;public long b;}
    public static class Samples {public Object f,g;Samples(float[] data,int rate){f=data;g=rate;}}
    public static class Model {int calls,speaker;float speed;String text;Runnable callback;boolean fail,silence;}
    public static class Backend {
        public android.content.Context a=RuntimeEnvironment.getApplication();public PendingExecutor c=new PendingExecutor();public Model d=new Model();public AudioTrack e;public boolean f=false;public int g;public String h="nl_NL-test-medium",language="nl";public Level level=new Level();public boolean replaced;
        public Model a(){return replaced?new Model():d;}public String b(){return language;}public int g(){return 2;}public Level c(String key){return level;}public void h(){g++;}
        public static Samples e(Model model,String text,int speaker,float speed){model.calls++;model.text=text;model.speaker=speaker;model.speed=speed;if(model.callback!=null)model.callback.run();if(model.fail)throw new IllegalStateException("Synthetic model failure");float[] pcm=new float[2205];for(int i=0;i<pcm.length;i++)pcm[i]=model.silence?0:(float)Math.sin(i*.2)*.1f;return new Samples(pcm,22050);}
    }
    static class Results implements VelaWarningSpeaker.Listener {int starts;List<PlaybackGrant.Outcome> outcomes=new ArrayList<>();List<Boolean> quiet=new ArrayList<>();public void started(PlaybackGrant g){starts++;}public void finished(PlaybackGrant g,PlaybackGrant.Outcome o,boolean q){outcomes.add(o);quiet.add(q);}}
    WarningEvent event(){long now=SystemClock.elapsedRealtime();Bundle b=new Bundle();b.putInt("protocol_version",1);b.putString("provider_session",UUID.randomUUID().toString());b.putLong("sequence",1);b.putString("operation","ANNOUNCE");b.putString("warning_id","test-native");b.putLong("revision",1);b.putLong("announcement_index",1);b.putString("phase","notice");b.putString("native_type","Incident");b.putString("category","road_danger");b.putInt("priority",0);b.putString("message","Synthetische testwaarschuwing");b.putString("language_tag","nl-NL");b.putString("message_origin","native_text");b.putString("relevance","notice");b.putString("relationship","unknown");b.putLong("observed_elapsed_ms",now);b.putLong("issued_elapsed_ms",now);b.putLong("announce_until_elapsed_ms",now+5000);b.putLong("state_until_elapsed_ms",now+30000);return WarningCodec.decode(b,now);}
    PlaybackGrant grant(WarningEvent e){return grant(e,WarningAudioOwner.Mode.VOICE);}
    PlaybackGrant grant(WarningEvent e,WarningAudioOwner.Mode mode){return grant(e,mode,null);}
    PlaybackGrant grant(WarningEvent e,WarningAudioOwner.Mode mode,WarningEvent authority){long now=SystemClock.elapsedRealtime();Set<String> caps=Collections.singleton("native_text");WarningCapabilities profile=new WarningCapabilities(String.join("",Collections.nCopies(64,"a")),caps,true);WarningJournal journal=new WarningJournal(e.providerSession);if(authority!=null)journal.append(authority,now);journal.append(e,now);WarningAudioOwner owner=new WarningAudioOwner("boot-count:1",e.providerSession,journal,new PlaybackStore(){public PlaybackGrant load(){return null;}public void save(PlaybackGrant g){}},profile);WarningAudioOwner.Client client=new WarningAudioOwner.Client(10001,"app.vela",UUID.randomUUID().toString(),UUID.randomUUID().toString(),caps,EnumSet.of(WarningAudioOwner.Mode.VOICE,WarningAudioOwner.Mode.TONE),profile.digest);WarningAudioOwner.Lease lease=owner.claim(10001,client,mode,true,now).lease;return owner.begin(10001,client,lease.token,lease.epoch,e.warningId,e.phase,e.announcementIndex,e.revision,UUID.randomUUID().toString(),now).grant;}
    void idle(){Shadows.shadowOf(Looper.getMainLooper()).idle();}
    @Test public void activeCancellationStopsOnlyOurQueueAndRestoresThroughFreshNativeInput(){Object route=new Object();NativeSession session=new NativeSession(guide,route);speaker.bindSession(session);WarningEvent e=event();PlaybackGrant grant=grant(e);speaker.speak(e,grant,results);VelaWarningSpeaker.dispatch(guide.closure);assertTrue(VelaWarningSpeaker.beforeSpeech(guide,false));speaker.cancel(grant);assertEquals(1,engine.stops);idle();assertEquals(Collections.singletonList(false),results.quiet);VelaWarningSpeaker.utteranceStopped(new NativeListener(guide),engine.id,false);idle();NavState current=new NavState();assertSame(current,VelaWarningSpeaker.regenerateInput(new Object(),current));NavState restored=(NavState)VelaWarningSpeaker.regenerateInput(route,current);assertNotSame(current,restored);assertTrue(restored.h.isEmpty());assertEquals(new HashSet<>(Arrays.asList(0,1)),current.h);assertEquals(current.a,restored.a);assertEquals(current.i,restored.i,0);assertEquals(current.b,restored.b,0);assertSame(current,VelaWarningSpeaker.regenerateInput(route,current));}
    @Test public void urgentWarningWaitsForNativePendingClosureToBeFencedBeforeSpeaking(){NativeSession session=new NativeSession(guide,new Object());speaker.bindSession(session);guide.s=1;Closure nativeClosure=new Closure(guide,engine);VelaWarningSpeaker.capture(nativeClosure);WarningEvent event=event();assertFalse(speaker.isReady(event.languageTag));assertTrue(speaker.canSpeak(event,WarningAudioOwner.Mode.VOICE));assertTrue(speaker.speak(event,grant(event),results));assertEquals(1,engine.stops);assertEquals(0,engine.calls);assertTrue(VelaWarningSpeaker.dispatch(nativeClosure));assertEquals(0,guide.s);idle();assertNotNull(guide.closure);assertTrue(VelaWarningSpeaker.dispatch(guide.closure));assertEquals(1,engine.calls);}
    @Test public void unavailableAdapterPreservesRequestedModeWithoutInventingUserMute(){speaker.bind(null);assertEquals(WarningAudioOwner.Mode.VOICE,speaker.effectiveMode(WarningAudioOwner.Mode.VOICE));assertFalse(speaker.isReady("nl",WarningAudioOwner.Mode.VOICE));assertEquals(WarningAudioOwner.Mode.TONE,speaker.effectiveMode(WarningAudioOwner.Mode.TONE));assertFalse(speaker.isReady("nl",WarningAudioOwner.Mode.TONE));assertTrue(speaker.isReady("nl",WarningAudioOwner.Mode.SILENT));speaker.bind(new Object());assertEquals(WarningAudioOwner.Mode.VOICE,speaker.effectiveMode(WarningAudioOwner.Mode.VOICE));assertFalse(speaker.isReady("nl",WarningAudioOwner.Mode.VOICE));}
    @Test public void systemToNeuralSwitchRetainsOnlyTheObservedSameFocusRequest(){WarningEvent first=event();PlaybackGrant grant=grant(first);assertTrue(speaker.speak(first,grant,results));VelaWarningSpeaker.dispatch(guide.closure);VelaWarningSpeaker.utteranceStart(new NativeListener(guide),engine.id);VelaWarningSpeaker.utteranceDone(new NativeListener(guide),engine.id);idle();assertEquals(1,guide.focusRequests);assertEquals(0,guide.s);assertTrue(guide.t);Backend backend=new Backend();VelaWarningSpeaker.engineChanging(guide);guide.l=backend;guide.m=true;VelaWarningSpeaker.engineChanged(guide);WarningEvent second=event();PlaybackGrant next=grant(second);assertTrue(speaker.speak(second,next,results));assertEquals(1,backend.c.jobs.size());assertEquals(1,guide.focusRequests);assertFalse(results.outcomes.contains(PlaybackGrant.Outcome.NOT_STARTED));speaker.cancel(next);backend.c.next();}
    @Test public void engineSwitchCannotInferGrantFromAnUnknownRetainedFlag(){VelaWarningSpeaker.focusResult(guide,AudioManager.AUDIOFOCUS_REQUEST_GRANTED);guide.t=true;VelaWarningSpeaker.engineChanging(guide);guide.q=new Object();Backend backend=new Backend();guide.l=backend;guide.m=true;VelaWarningSpeaker.engineChanged(guide);WarningEvent event=event();assertTrue(speaker.speak(event,grant(event),results));idle();assertTrue(backend.c.jobs.isEmpty());assertEquals(Collections.singletonList(PlaybackGrant.Outcome.NOT_STARTED),results.outcomes);}
    @Test public void newDelayedFocusResultDuringEngineSwitchCannotRestoreAnOlderGrant(){VelaWarningSpeaker.focusResult(guide,AudioManager.AUDIOFOCUS_REQUEST_GRANTED);guide.t=true;VelaWarningSpeaker.engineChanging(guide);VelaWarningSpeaker.focusRequest(guide);VelaWarningSpeaker.focusResult(guide,AudioManager.AUDIOFOCUS_REQUEST_DELAYED);Backend backend=new Backend();guide.l=backend;guide.m=true;VelaWarningSpeaker.engineChanged(guide);WarningEvent event=event();assertTrue(speaker.speak(event,grant(event),results));idle();assertTrue(backend.c.jobs.isEmpty());assertEquals(Collections.singletonList(PlaybackGrant.Outcome.NOT_STARTED),results.outcomes);}
    @Test public void engineSwitchFencesPendingClosureAndBalancesItsFocusBeforeNewNeuralWork(){WarningEvent first=event();PlaybackGrant original=grant(first);speaker.speak(first,original,results);Closure pending=guide.closure;Backend backend=new Backend();VelaWarningSpeaker.engineChanging(guide);guide.l=backend;guide.m=true;VelaWarningSpeaker.engineChanged(guide);assertEquals(0,guide.s);assertEquals(1,guide.releases);assertTrue(VelaWarningSpeaker.dispatch(pending));assertEquals(0,engine.calls);WarningEvent second=event();PlaybackGrant next=grant(second);assertTrue(speaker.speak(second,next,results));assertEquals(1,backend.c.jobs.size());assertEquals(1,guide.s);speaker.cancel(next);backend.c.next();assertEquals(0,guide.s);assertEquals(2,guide.releases);}
    @Test public void selectedNeuralReadinessRequiresLoadedMatchingLanguageModel(){Backend backend=new Backend();guide.l=backend;guide.m=true;assertTrue(speaker.isReady("nl-NL"));assertFalse(speaker.isReady("en-US"));backend.d=null;assertFalse(speaker.isReady("nl"));backend.d=new Model();backend.f=true;assertFalse(speaker.isReady("nl"));}
    @Test public void neuralPendingCancellationCarriesIdentityAcrossNativeWorkerQueue(){Backend backend=new Backend();guide.l=backend;guide.m=true;WarningEvent e=event();PlaybackGrant grant=grant(e);assertTrue(speaker.speak(e,grant,results));assertEquals(1,backend.c.jobs.size());assertEquals(0,backend.d.calls);assertEquals(0,results.starts);speaker.cancel(grant);backend.c.next();idle();assertEquals(0,backend.d.calls);assertEquals(Collections.singletonList(PlaybackGrant.Outcome.CANCELLED),results.outcomes);assertEquals(Collections.singletonList(true),results.quiet);assertEquals(1,guide.releases);}
    @Test public void neuralCancellationAfterSynthesisFencesQueuedPlayer(){Backend backend=new Backend();guide.l=backend;guide.m=true;WarningEvent event=event();PlaybackGrant grant=grant(event);assertTrue(speaker.speak(event,grant,results));backend.c.next();assertEquals(1,backend.d.calls);assertEquals(1,outputs.jobs.size());assertEquals(0,results.starts);speaker.cancel(grant);outputs.next();idle();assertEquals(Collections.singletonList(PlaybackGrant.Outcome.CANCELLED),results.outcomes);assertEquals(Collections.singletonList(true),results.quiet);assertEquals(1,guide.releases);}
    @Test public void neuralNativeGenerationAndModelReplacementRejectBeforeSynthesis(){for(boolean replaced:new boolean[]{false,true}){Backend backend=new Backend();guide.l=backend;guide.m=true;WarningEvent e=event();assertTrue(speaker.speak(e,grant(e),results));if(replaced)backend.replaced=true;else backend.g++;backend.c.next();idle();assertEquals(0,backend.d.calls);assertEquals(PlaybackGrant.Outcome.NOT_STARTED,results.outcomes.get(results.outcomes.size()-1));}}
    @Test public void neuralUsesOriginalSelectedModelSpeakerSpeedAndTextWithoutEquatingSynthesisToPlayback(){Backend backend=new Backend();guide.l=backend;guide.m=true;backend.a.getSharedPreferences("vela_settings",0).edit().putFloat("voice_speed",1.5f).commit();WarningEvent event=event();PlaybackGrant grant=grant(event);assertTrue(speaker.speak(event,grant,results));backend.d.callback=()->speaker.cancel(grant);backend.c.next();idle();assertEquals(1,backend.d.calls);assertEquals(event.message,backend.d.text);assertEquals(2,backend.d.speaker);assertEquals(1.5f,backend.d.speed,0);assertEquals(0,results.starts);assertEquals(Collections.singletonList(PlaybackGrant.Outcome.CANCELLED),results.outcomes);}
    @Test public void neuralSynthesisFailureNeverReportsStartedOrCompleted(){Backend backend=new Backend();guide.l=backend;guide.m=true;backend.d.fail=true;WarningEvent event=event();assertTrue(speaker.speak(event,grant(event),results));backend.c.next();idle();assertEquals(0,results.starts);assertEquals(Collections.singletonList(PlaybackGrant.Outcome.FAILED),results.outcomes);assertEquals(Collections.singletonList(true),results.quiet);}
    @Test public void revisedTextKeepsOriginalAnnouncementAuthorityAndDeadline(){WarningEvent authority=event();Bundle changed=WarningCodec.encode(authority);changed.putString("operation","UPSERT");changed.putLong("sequence",2);changed.putLong("revision",2);changed.putString("message","Bijgewerkte synthetische waarschuwing");changed.remove("announce_until_elapsed_ms");WarningEvent payload=WarningCodec.decode(changed,SystemClock.elapsedRealtime());PlaybackGrant grant=grant(payload,WarningAudioOwner.Mode.VOICE,authority);assertFalse(speaker.speak(payload,grant,results));assertTrue(speaker.speak(payload,grant,authority.announceUntil,results));assertTrue(VelaWarningSpeaker.dispatch(guide.closure));assertEquals(payload.message,engine.text);}
    @Test public void expiredOriginalDeadlineCannotBeExtendedByRevisedText(){WarningEvent authority=event();Bundle changed=WarningCodec.encode(authority);changed.putString("operation","UPSERT");changed.putLong("sequence",2);changed.putLong("revision",2);WarningEvent payload=WarningCodec.decode(changed,SystemClock.elapsedRealtime());PlaybackGrant grant=grant(payload,WarningAudioOwner.Mode.VOICE,authority);assertFalse(speaker.speak(payload,grant,SystemClock.elapsedRealtime(),results));assertEquals(0,engine.calls);}
    @Test public void selectedEngineAndLanguagePreserveNativeTextAndEnqueueIsNotStart(){WarningEvent e=event();PlaybackGrant g=grant(e);assertTrue(speaker.isReady(e.languageTag));assertTrue(speaker.speak(e,g,results));assertEquals(0,engine.calls);assertTrue(VelaWarningSpeaker.dispatch(guide.closure));assertEquals(e.message,engine.text);assertEquals("nl",engine.language.getLanguage());assertEquals("nl-NL",guide.j);assertEquals("nl",guide.preflightLanguage);assertEquals("fr",VelaWarningSpeaker.language(guide,"fr"));assertEquals(0,results.starts);assertTrue(VelaWarningSpeaker.utterance(new NativeListener(guide),engine.id,0));idle();assertEquals(1,results.starts);assertTrue(VelaWarningSpeaker.utteranceDone(new NativeListener(guide),engine.id));idle();assertEquals(Collections.singletonList(PlaybackGrant.Outcome.COMPLETED),results.outcomes);assertEquals(1,guide.releases);assertFalse(speaker.speak(e,g,results));}
    @Test public void pendingCancelRejectsClosureAndBalancesOnlyItsAcquisition(){WarningEvent e=event();PlaybackGrant g=grant(e);assertTrue(speaker.speak(e,g,results));speaker.cancel(g);assertTrue(VelaWarningSpeaker.dispatch(guide.closure));idle();assertEquals(0,engine.calls);assertEquals(1,guide.releases);assertEquals(Collections.singletonList(PlaybackGrant.Outcome.CANCELLED),results.outcomes);assertEquals(Collections.singletonList(true),results.quiet);VelaWarningSpeaker.dispatch(guide.closure);assertEquals(1,guide.releases);}
    @Test public void nativeStopInvalidatesLeadWithoutDecrementingNewNativeRoute(){WarningEvent e=event();assertTrue(speaker.speak(e,grant(e),results));VelaWarningSpeaker.nativeStop(guide);guide.s=1;VelaWarningSpeaker.dispatch(guide.closure);idle();assertEquals(0,engine.calls);assertEquals(0,guide.releases);assertEquals(1,guide.s);}
    @Test public void deniedOrDelayedFocusNeverSubmitsSpeech(){for(int focus:new int[]{AudioManager.AUDIOFOCUS_REQUEST_FAILED,AudioManager.AUDIOFOCUS_REQUEST_DELAYED}){guide.request=focus;WarningEvent e=event();assertTrue(speaker.speak(e,grant(e),results));VelaWarningSpeaker.dispatch(guide.closure);idle();assertEquals(0,engine.calls);assertEquals(PlaybackGrant.Outcome.NOT_STARTED,results.outcomes.get(results.outcomes.size()-1));}}
    @Test public void submittedCancellationRetainsFenceUntilActualTerminalAndLateStartIsReported(){WarningEvent e=event();PlaybackGrant g=grant(e);speaker.speak(e,g,results);VelaWarningSpeaker.dispatch(guide.closure);String id=engine.id;speaker.cancel(g);VelaWarningSpeaker.utteranceStart(new NativeListener(guide),id);idle();assertEquals(1,results.starts);assertEquals(Collections.singletonList(false),results.quiet);assertFalse(speaker.isReady(e.languageTag));VelaWarningSpeaker.utteranceStopped(new NativeListener(guide),id,false);idle();assertEquals(Arrays.asList(false,true),results.quiet);assertTrue(speaker.isReady(e.languageTag));assertEquals(1,guide.releases);VelaWarningSpeaker.utteranceDone(new NativeListener(guide),id);assertEquals(1,guide.releases);}
    @Test public void nativeStopAfterSubmissionAndLateTerminalCannotReleaseANewerRoute(){WarningEvent e=event();speaker.speak(e,grant(e),results);VelaWarningSpeaker.dispatch(guide.closure);String id=engine.id;VelaWarningSpeaker.nativeStop(guide);guide.s=1;VelaWarningSpeaker.utteranceStopped(new NativeListener(guide),id,false);idle();assertEquals(0,guide.releases);assertEquals(1,guide.s);assertEquals(Arrays.asList(false,true),results.quiet);}
    @Test public void submissionFailureAndModeCapsAreTruthful(){engine.result=TextToSpeech.ERROR;WarningEvent e=event();speaker.speak(e,grant(e),results);VelaWarningSpeaker.dispatch(guide.closure);idle();assertEquals(Collections.singletonList(PlaybackGrant.Outcome.FAILED),results.outcomes);assertEquals(Collections.singletonList(true),results.quiet);guide.n=true;guide.o=true;assertEquals(WarningAudioOwner.Mode.TONE,speaker.effectiveMode(WarningAudioOwner.Mode.VOICE));assertTrue(speaker.isReady("nl",WarningAudioOwner.Mode.TONE));guide.o=false;assertEquals(WarningAudioOwner.Mode.SILENT,speaker.effectiveMode(WarningAudioOwner.Mode.VOICE));guide.n=false;guide.m=true;assertFalse(speaker.isReady("nl"));}
    @Test public void nativeRouteArrivalCancelsOnlyOwnedToneAndBalancesNativeFocus(){guide.n=true;guide.o=true;WarningEvent base=event();Bundle normal=WarningCodec.encode(base);normal.putInt("priority",1);WarningEvent e=WarningCodec.decode(normal,SystemClock.elapsedRealtime());PlaybackGrant g=grant(e,WarningAudioOwner.Mode.TONE);assertTrue(speaker.speak(e,g,results));VelaWarningSpeaker.nativeSpeech(guide);idle();assertEquals(PlaybackGrant.Outcome.CANCELLED,results.outcomes.get(0));assertTrue(results.quiet.get(0));assertEquals(1,guide.releases);assertEquals(0,engine.calls);}
    @Test public void providerSoundPlaysFirstThenTheSameAttemptSpeaksItsText(){
        nl.johninnl.navigation.alerts.ProviderSound.remember(nl.johninnl.navigation.alerts.ProviderSound.FLITSMEISTER,"flitser.m4a",new nl.johninnl.navigation.alerts.ProviderSound.Pcm(new short[2205],22050,1));
        Bundle encoded=WarningCodec.encode(event());encoded.putString("native_sound","flitser.m4a");WarningEvent e=WarningCodec.decode(encoded,SystemClock.elapsedRealtime());
        PlaybackGrant g=grant(e);assertTrue(speaker.speak(e,g,results));
        assertNull("Speech waits for the provider sound",guide.closure);assertEquals(1,outputs.jobs.size());
        outputs.next();idle();
        assertNotNull("The same attempt continues with the spoken text",guide.closure);
        VelaWarningSpeaker.dispatch(guide.closure);assertEquals(1,engine.calls);assertEquals(e.message,engine.text);
        assertTrue(results.outcomes.isEmpty());
    }
    @Test public void toneModeUsesTheProviderSoundInsteadOfTheChimeAndNeverSpeaks(){
        guide.n=true;guide.o=true;
        nl.johninnl.navigation.alerts.ProviderSound.remember(nl.johninnl.navigation.alerts.ProviderSound.FLITSMEISTER,"trajectcontrole_start.m4a",new nl.johninnl.navigation.alerts.ProviderSound.Pcm(new short[2205],22050,1));
        Bundle encoded=WarningCodec.encode(event());encoded.putString("native_sound","trajectcontrole_start.m4a");WarningEvent e=WarningCodec.decode(encoded,SystemClock.elapsedRealtime());
        PlaybackGrant g=grant(e,WarningAudioOwner.Mode.TONE);assertTrue(speaker.speak(e,g,results));
        outputs.next();idle();
        assertEquals(1,results.outcomes.size());assertNull(guide.closure);assertEquals(0,engine.calls);
    }
    @Test public void staticToneMustWriteItsInitialBufferBeforeRequiringInitializedState(){StaticTrack track=new StaticTrack();assertEquals(AudioTrack.STATE_NO_STATIC_DATA,track.getState());assertTrue(VelaWarningSpeaker.loadTone(track,VelaWarningSpeaker.tonePcm()));assertEquals(1,track.writes);assertEquals(AudioTrack.STATE_INITIALIZED,track.getState());track.release();}
    @Test public void incompleteStaticToneWriteOrInvalidTrackCannotReachPlayback(){for(int scenario=0;scenario<3;scenario++){StaticTrack track=new StaticTrack();if(scenario==0)track.partial=true;else if(scenario==1)track.badAfter=true;else track.state=AudioTrack.STATE_UNINITIALIZED;assertFalse(VelaWarningSpeaker.loadTone(track,VelaWarningSpeaker.tonePcm()));assertEquals(scenario==2?0:1,track.writes);track.release();}}
    @Test public void toneRetainsNativePcmEnvelopeAndGap(){short[] pcm=VelaWarningSpeaker.tonePcm();int note=22050*110/1000;assertEquals(note*2+661,pcm.length);assertEquals(0,pcm[0]);assertEquals(0,pcm[note-1]);for(int i=note;i<note+661;i++)assertEquals(0,pcm[i]);assertArrayEquals(Arrays.copyOfRange(pcm,0,note),Arrays.copyOfRange(pcm,note+661,pcm.length));int peak=0;for(short sample:pcm)peak=Math.max(peak,Math.abs((int)sample));assertTrue(peak>9000 && peak<=9500);}
    @Test public void untaggedNativeClosuresAndListenerIdsKeepOriginalPath(){assertFalse(VelaWarningSpeaker.dispatch(new Closure(guide,engine)));assertFalse(VelaWarningSpeaker.utteranceDone(new NativeListener(guide),"vela-12345"));assertEquals(0,guide.releases);}
